// PARSER IMAGES — normalise la sortie : direction artistique commune + prompts par image.
// Réinjecte l'art_direction dans chaque prompt pour garantir la cohérence de série même si
// le modèle a été inégal.
let raw = $input.first().json.choices?.[0]?.message?.content || '{}';
raw = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();

let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }

let liste = Array.isArray(parsed) ? parsed : (parsed.images || Object.values(parsed).find(v => Array.isArray(v)) || []);
const art_direction = (!Array.isArray(parsed) && parsed.art_direction) ? parsed.art_direction : {};

const adResume = [art_direction.style, art_direction.mood, art_direction.lighting, art_direction.color_palette, art_direction.composition, art_direction.camera]
  .filter(Boolean).join(', ');

const slugify = (s) => (s || '').toString().toLowerCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const negDefaut = 'text, watermark, third-party logos, distorted faces, extra fingers, low quality, blurry, cartoon, 3d kitsch, oversaturated, stock photo cliché, deformed';

const image_prompts = liste.map((p, i) => {
  const role = p.role || (i === 0 ? 'featured' : 'inline');
  let prompt = (p.prompt || '').toString().trim();
  // Garantit la cohérence de série : préfixe la direction artistique commune si absente.
  if (adResume && prompt && !prompt.toLowerCase().includes('editorial')) {
    prompt = `${prompt} — consistent art direction: ${adResume}. Professional editorial photography, photorealistic, ultra HD.`;
  }
  return {
    name: p.name || (i === 0 ? 'hero' : `section-${i}`),
    role,
    generator: 'Google Nano Banana (Gemini 2.5 Flash Image)',
    filename: p.filename || `${slugify(p.name || 'image-' + (i + 1))}.webp`,
    prompt,
    negative_prompt: p.negative_prompt || negDefaut,
    aspect_ratio: p.aspect_ratio || (role === 'featured' ? '16:9' : '4:3'),
    alt_text: p.alt_text || '',
    title: p.title || '',
    caption: p.caption || ''
  };
});

