const strategie = $('Parser Analyse SEO').first().json.strategie || {};
const keywords_data = ctx.keywords_data || {};
const gsc_data = ctx.gsc_data || [];
const profil_site = ctx.profil_site || {};
const palette = ctx.palette || {};
const concurrents = (ctx.concurrents || []).map(c => ({ source: c.source, titre: c.titre }));

const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const words = text ? text.split(' ').length : 0;
const kw = (inputs.mot_cle || '').toLowerCase().trim();
const lowerText = text.toLowerCase();
const kwCount = kw ? (lowerText.split(kw).length - 1) : 0;
const density = words ? +(kwCount / words * 100).toFixed(2) : 0;
const h1 = (html.match(/<h1[\s>]/gi) || []).length + (acf.article_titre ? 0 : 0);
const h2 = (html.match(/<h2[\s>]/gi) || []).length;
const h3 = (html.match(/<h3[\s>]/gi) || []).length;
const links = (html.match(/<a\s[^>]*href/gi) || []).length;
const hasList = /<(ul|ol)[\s>]/i.test(html);
const hasTable = /<table[\s>]/i.test(html);
const hasAside = /<aside[\s>]/i.test(html);      // answer capsule AEO/GEO
const hasDetails = /<details[\s>]/i.test(html);  // FAQ accordéon
const hasFaq = hasDetails || /faq/i.test(html) || (meta.json_ld_faq && Object.keys(meta.json_ld_faq).length > 0);
const usesBrand = palette.couleur_marque ? html.toLowerCase().includes(palette.couleur_marque.toLowerCase()) : true;
const titleLen = (meta.seo_title || '').length;
const descLen = (meta.meta_description || '').length;
const firstPara = ((html.match(/<p[^>]*>([\s\S]*?)<\/p>/i) || [null, ''])[1] || '').toLowerCase();
const kwInTitle = !!kw && (meta.seo_title || '').toLowerCase().includes(kw);
const kwInIntro = !!kw && firstPara.includes(kw);
const readingTime = Math.max(1, Math.round(words / 200)) + ' min';
const nbBlocs = Array.isArray(data.blocs) ? data.blocs.length : 0;

const checks = [];
const add = (ok, poids, label) => checks.push({ ok: !!ok, poids, label });
add(words >= (inputs.longueur || 800) * 0.8, 14, `Longueur suffisante (${words} mots)`);
add(nbBlocs >= (parseInt(inputs.nb_blocs) || 7) - 1, 8, `Nombre de blocs ACF (${nbBlocs})`);
add(h2 >= 3, 7, `Au moins 3 sections H2 (${h2})`);
add(kwInTitle, 9, 'Mot-clé présent dans le title SEO');
add(kwInIntro, 8, "Mot-clé dans l'intro (AEO : réponse directe)");
add(hasAside, 7, 'Answer Capsule (<aside> AEO/GEO) présente');
add(density >= 0.3 && density <= 3, 7, `Densité du mot-clé saine (${density}%)`);
add(titleLen > 0 && titleLen <= 60, 5, `Title <= 60 caractères (${titleLen})`);
add(descLen >= 120 && descLen <= 160, 6, `Meta description 120-160 (${descLen})`);
add(links >= 2, 5, `Au moins 2 liens (${links})`);
add(hasFaq, 6, 'Section FAQ présente (<details> / PAA)');
add(hasList || hasTable, 6, 'Liste ou tableau (featured snippet)');
add(usesBrand, 5, 'Charte couleur de marque appliquée');
add(Array.isArray(meta.secondary_keywords) && meta.secondary_keywords.length >= 3, 3, 'Au moins 3 mots-clés secondaires');
add(meta.json_ld_article && Object.keys(meta.json_ld_article).length > 0, 4, 'Schema.org Article présent');

const gagne = checks.reduce((s, c) => s + (c.ok ? c.poids : 0), 0);
const total = checks.reduce((s, c) => s + c.poids, 0);
const note = Math.round(gagne / total * 100);
const avertissements = checks.filter(c => !c.ok).map(c => c.label);

const seo_audit = {
  score: note, sur: 100,
  statut: note >= (inputs.seuil_qualite || 70) ? 'VALIDE' : 'A_REVOIR',
  mots: words, temps_lecture: readingTime, densite_mot_cle: density + '%', occurrences_mot_cle: kwCount,
  structure: { blocs: nbBlocs, h2, h3, liens: links, liste: hasList, tableau: hasTable, answer_capsule: hasAside, faq: !!hasFaq },
  longueurs: { title: titleLen, meta_description: descLen },
  avertissements, controles: checks
};

